function bbs_designer_upload_asset(string $field): array { $file=$_FILES[$field]??null;if(!is_array($file)||(int)($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)json_response(['success'=>false,'message'=>'A JPG, PNG, or WebP designer image is required.'],400);if((int)($file['size']??0)>10*1024*1024)json_response(['success'=>false,'message'=>'Designer image must not exceed 10 MB.'],400);$mime=bbs_card_file_mime((string)$file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['success'=>false,'message'=>'Designer image content must be JPEG, PNG, or WebP.'],400);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=bbs_designer_asset_dir().'/'.basename($stored);if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'message'=>'Unable to store designer image.'],500);return['stored'=>$stored,'target'=>$target,'name'=>bbs_card_clean($file['name']??'image',255),'mime'=>$mime,'size'=>(int)$file['size']]; }
