function bbs_designer_detail(int $id,?PDO $pdo=null,bool $lock=false,bool $includeDeleted=false): ?array {
    $pdo=$pdo?:db();$stmt=$pdo->prepare('SELECT * FROM BBS_Card_Layout_Versions WHERE id=?'.($includeDeleted?'':' AND IsDeleted=0').($lock?' FOR UPDATE':''));$stmt->execute([$id]);$version=$stmt->fetch();if(!$version)return null;
    $stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=? ORDER BY FIELD(Side,'Front','Back')");$stmt->execute([$id]);$sides=$stmt->fetchAll();
    $stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Elements WHERE LayoutVersionID=? ORDER BY FIELD(Side,'Front','Back'),ZIndex,id");$stmt->execute([$id]);$elements=$stmt->fetchAll();
    $stmt=$pdo->prepare("SELECT a.*,m.TemplateKind MasterArtworkKind,m.Side MasterArtworkSide FROM BBS_Card_Layout_Assets a LEFT JOIN BBS_Card_Master_Artwork m ON m.id=a.MasterArtworkID WHERE a.LayoutVersionID=? AND a.Status='Active' ORDER BY a.CreatedAt,a.id");$stmt->execute([$id]);return bbs_designer_row_layout($version,$sides,$elements,$stmt->fetchAll());
}
function bbs_designer_insert_content(PDO $pdo,int $versionId,array $layout): void {
