    foreach($layout['sides'] as$item)$side->execute([$versionId,$item['side'],$item['storageClass'],$item['backgroundStoredName'],$item['backgroundOriginalName'],$item['backgroundMimeType'],$item['backgroundFileSize'],$item['pixelWidth'],$item['pixelHeight'],$item['backgroundFit'],$item['backgroundPositionXBP'],$item['backgroundPositionYBP'],$item['bleedMM'],$item['safeMarginMM']]);
    $element=$pdo->prepare('INSERT INTO BBS_Card_Layout_Elements(LayoutVersionID,ElementKey,Side,ElementType,DataSourceKey,StaticText,AssetID,XBP,YBP,WidthBP,HeightBP,RotationDeg,ZIndex,Visible,Locked,Required,StyleJSON) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
    foreach($layout['elements'] as$item)$element->execute([$versionId,$item['elementKey'],$item['side'],$item['elementType'],$item['dataSourceKey'],$item['staticText'],$item['assetId'],$item['xBP'],$item['yBP'],$item['widthBP'],$item['heightBP'],$item['rotationDeg'],$item['zIndex'],$item['visible'],$item['locked'],$item['required'],json_encode($item['style'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
}
