function bbs_designer_canonicalize_resources(PDO $pdo,array $version,array $layout): array {
    $info=bbs_designer_kind_info((string)$version['TemplateKind']);$parentId=(int)$version[$info['parentColumn']];$stmt=$pdo->prepare("SELECT * FROM {$info['parentTable']} WHERE id=?");$stmt->execute([$parentId]);$parent=$stmt->fetch();if(!$parent)throw new InvalidArgumentException('Parent template was not found.');
    $stmt=$pdo->prepare("SELECT a.*,m.TemplateKind MasterArtworkKind,m.Side MasterArtworkSide FROM BBS_Card_Layout_Assets a LEFT JOIN BBS_Card_Master_Artwork m ON m.id=a.MasterArtworkID WHERE a.LayoutVersionID=? AND a.Status='Active'");$stmt->execute([(int)$version['id']]);$assets=$stmt->fetchAll();$byId=[];foreach($assets as$asset)$byId[(int)$asset['id']]=$asset;
