    foreach($layout['sides']as$index=>$side){if($side['storageClass']!=='DesignerAsset')throw new BbsMasterArtworkException($info['kind'].' '.$side['side'].' background must use Master Artwork.');$asset=$byId[(int)($side['backgroundAssetId']??0)]??null;if(!$asset)throw new BbsMasterArtworkException('Designer background must reference an uploaded Master Artwork snapshot from this Draft.');if(empty($asset['MasterArtworkID'])||$asset['MasterArtworkKind']!==$info['kind']||$asset['MasterArtworkSide']!==$side['side'])throw new BbsMasterArtworkException($info['kind'].' '.$side['side'].' background must use its matching Master Artwork snapshot.');$layout['sides'][$index]=array_merge($side,['backgroundAssetId'=>(int)$asset['id'],'masterArtworkId'=>(int)$asset['MasterArtworkID'],'masterArtworkKind'=>$asset['MasterArtworkKind'],'masterArtworkSide'=>$asset['MasterArtworkSide'],'backgroundStoredName'=>$asset['StoredName'],'backgroundOriginalName'=>$asset['OriginalName'],'backgroundMimeType'=>$asset['MimeType'],'backgroundFileSize'=>(int)$asset['FileSize'],'pixelWidth'=>$asset['PixelWidth']===null?null:(int)$asset['PixelWidth'],'pixelHeight'=>$asset['PixelHeight']===null?null:(int)$asset['PixelHeight']]);}
    return$layout;
