function bbs_designer_master_snapshot(PDO $pdo,int $versionId,string $kind,array $layout,string $actor,array &$createdFiles): array {
    $info=bbs_designer_kind_info($kind);$stmt=$pdo->prepare("SELECT p.id FROM BBS_Card_Layout_Versions v JOIN {$info['parentTable']} p ON p.id=v.{$info['parentColumn']} WHERE v.id=? AND p.IsDeleted=0");$stmt->execute([$versionId]);if(!$stmt->fetch())throw new InvalidArgumentException('A Designer Draft cannot be created for a template in Trash.');
    $stmt=$pdo->prepare("SELECT * FROM BBS_Card_Master_Artwork WHERE TemplateKind=? AND Status='Active' ORDER BY FIELD(Side,'Front','Back') FOR UPDATE");$stmt->execute([$kind]);$bySide=[];foreach($stmt->fetchAll()as$row)$bySide[$row['Side']]=$row;
    foreach(['Front','Back']as$side)if(!isset($bySide[$side]))throw new BbsMasterArtworkException("$kind $side Master Artwork is required before creating a Designer Draft.");
    foreach($layout['sides']as$index=>$side){$master=$bySide[$side['side']];$source=bbs_designer_master_dir().'/'.basename((string)$master['StoredName']);if(!is_file($source)||bbs_card_file_mime($source)!==$master['MimeType'])throw new BbsMasterArtworkException($kind.' '.$side['side'].' Master Artwork file is unavailable.');$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$master['MimeType']];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=bbs_designer_asset_dir().'/'.basename($stored);if(!copy($source,$target))throw new RuntimeException('Unable to snapshot Master Artwork.');$createdFiles[]=$target;$stmt=$pdo->prepare("INSERT INTO BBS_Card_Layout_Assets(LayoutVersionID,MasterArtworkID,AssetKey,StoredName,OriginalName,MimeType,FileSize,PixelWidth,PixelHeight,Status,CreatedBy) VALUES(?,?,?,?,?,?,?,?,?,'Active',?)");$stmt->execute([$versionId,$master['id'],'master-'.strtolower($side['side']).'-v'.$master['VersionNo'],$stored,$master['OriginalName'],$master['MimeType'],$master['FileSize'],$master['PixelWidth'],$master['PixelHeight'],$actor]);$layout['sides'][$index]=array_merge($side,['storageClass'=>'DesignerAsset','backgroundAssetId'=>(int)$pdo->lastInsertId(),'masterArtworkId'=>(int)$master['id'],'masterArtworkKind'=>$kind,'masterArtworkSide'=>$side['side'],'backgroundStoredName'=>$stored,'backgroundOriginalName'=>$master['OriginalName'],'backgroundMimeType'=>$master['MimeType'],'backgroundFileSize'=>(int)$master['FileSize'],'pixelWidth'=>$master['PixelWidth']===null?null:(int)$master['PixelWidth'],'pixelHeight'=>$master['PixelHeight']===null?null:(int)$master['PixelHeight']]);}
