function bbs_designer_error(Throwable $error): void { if($error instanceof BbsMasterArtworkException)json_response(['success'=>false,'code'=>'MASTER_ARTWORK_REQUIRED','message'=>$error->getMessage()],409);if($error instanceof InvalidArgumentException)json_response(['success'=>false,'code'=>'BBS_DESIGNER_VALIDATION_FAILED','message'=>$error->getMessage()],400);if(($error instanceof PDOException)&&in_array((int)($error->errorInfo[1]??0),[1054,1146],true))json_response(['success'=>false,'code'=>'BBS_DESIGNER_SETUP_REQUIRED','message'=>'The latest BBS card Designer database migration is required.'],503);if(($error instanceof PDOException)&&($error->errorInfo[1]??null)===1062)json_response(['success'=>false,'code'=>'VERSION_CONFLICT','message'=>'The layout version conflicts with an existing record.'],409);throw$error; }

function handle_bbs_card_designer_routes(string $method,string $path): bool {
    if(strpos($path,'/bbs/admin/card-designer')!==0&&strpos($path,'/bbs/admin/card-master-artwork')!==0&&strpos($path,'/bbs/admin/card-layout-presets')!==0)return false;$admin=require_admin();
    try{
        if($method==='GET'&&$path==='/bbs/admin/card-master-artwork'){$records=array_map('bbs_designer_master_payload',db_rows("SELECT * FROM BBS_Card_Master_Artwork ORDER BY FIELD(TemplateKind,'Personal','Department'),FIELD(Side,'Front','Back'),VersionNo DESC,id DESC"));$slots=['Personal'=>['Front'=>null,'Back'=>null],'Department'=>['Front'=>null,'Back'=>null]];foreach($records as$row)if($row['status']==='Active')$slots[$row['templateKind']][$row['side']]=$row;json_response(['success'=>true,'data'=>['slots'=>$slots,'records'=>$records]]);}
        $masterUpload=route_params($path,'/bbs/admin/card-master-artwork/:kind/:side');if($method==='POST'&&$masterUpload!==null){bbs_designer_require_enabled();$kind=bbs_designer_kind($masterUpload['kind']);$side=ucfirst(strtolower(bbs_designer_clean($masterUpload['side'],10)));if(!in_array($side,['Front','Back'],true))throw new InvalidArgumentException('Master Artwork side must be Front or Back.');$upload=bbs_designer_upload_master('artwork');$pdo=db();$pdo->beginTransaction();try{$stmt=$pdo->prepare("SELECT id FROM BBS_Card_Master_Artwork WHERE TemplateKind=? AND Side=? AND Status='Active' FOR UPDATE");$stmt->execute([$kind,$side]);$stmt=$pdo->prepare('SELECT COALESCE(MAX(VersionNo),0)+1 nextNo FROM BBS_Card_Master_Artwork WHERE TemplateKind=? AND Side=?');$stmt->execute([$kind,$side]);$next=(int)$stmt->fetch()['nextNo'];$stmt=$pdo->prepare("UPDATE BBS_Card_Master_Artwork SET Status='Archived',ArchivedAt=NOW() WHERE TemplateKind=? AND Side=? AND Status='Active'");$stmt->execute([$kind,$side]);$stmt=$pdo->prepare("INSERT INTO BBS_Card_Master_Artwork(TemplateKind,Side,VersionNo,StoredName,OriginalName,MimeType,FileSize,PixelWidth,PixelHeight,Status,CreatedBy,ActivatedAt) VALUES(?,?,?,?,?,?,?,?,?,'Active',?,NOW())");$stmt->execute([$kind,$side,$next,$upload['stored'],$upload['name'],$upload['mime'],$upload['size'],$upload['width'],$upload['height'],$admin['id']]);$id=(int)$pdo->lastInsertId();$pdo->commit();bbs_phase1_audit($admin,'BBS_CARD_MASTER_ARTWORK_ACTIVATE','BBS_Card_Master_Artwork',(string)$id,"Activated $kind $side Master Artwork.");json_response(['success'=>true,'data'=>bbs_designer_master_payload(db_row('SELECT * FROM BBS_Card_Master_Artwork WHERE id=?',[$id]))],201);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();if(is_file($upload['target']))@unlink($upload['target']);throw$e;}}
